import re


def parse_select(sql: str) -> dict:
    m = re.match(
        r'\s*SELECT\s+(?P<cols>.+?)\s+FROM\s+(?P<rest>.*)$',
        sql, re.IGNORECASE | re.DOTALL,
    )
    if not m:
        raise ValueError("Invalid SELECT statement")

    columns = [c.strip() for c in m.group('cols').split(',')]

    wm = re.match(
        r'\s*(?P<table>\S+?)(?:\s+WHERE\s+(?P<where>.*))?\s*$',
        m.group('rest'), re.IGNORECASE | re.DOTALL,
    )
    table = wm.group('table')
    where = wm.group('where')

    return {'columns': columns, 'table': table, 'where': where}

