def evaluate(expr: str) -> float:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    # ---- Tokenizer ----
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or c == '.':
            j = i
            dots = 0
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    dots += 1
                j += 1
            if dots > 1:
                raise ValueError("Invalid number literal")
            num_str = expr[i:j]
            if num_str == '.':
                raise ValueError("Invalid number literal")
            tokens.append(('num', float(num_str)))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")
    if not tokens:
        raise ValueError("Empty expression")

    # ---- Recursive descent parser ----
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expr():
        left = parse_term()
        while True:
            tok = peek()
            if tok and tok[0] in ('+', '-'):
                advance()
                right = parse_term()
                left = left + right if tok[0] == '+' else left - right
            else:
                break
        return left

    def parse_term():
        left = parse_factor()
        while True:
            tok = peek()
            if tok and tok[0] in ('*', '/'):
                advance()
                right = parse_factor()
                if tok[0] == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ValueError("Division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        tok = peek()
        if tok and tok[0] == '+':
            advance()
            return parse_factor()
        if tok and tok[0] == '-':
            advance()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'num':
            advance()
            return tok[1]
        if tok[0] == '(':
            advance()
            value = parse_expr()
            closing = peek()
            if closing is None or closing[0] != ')':
                raise ValueError("Missing closing parenthesis")
            advance()
            return value
        raise ValueError(f"Unexpected token: {tok[0]!r}")

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("Trailing tokens after expression")
    return result

def evaluate(expr: str) -> float:
    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            num_str = expr[i:j]
            if num_str.count('.') > 1:
                raise ValueError(f"Invalid number: {num_str}")
            tokens.append(float(num_str))
            i = j
        else:
            raise ValueError(f"Invalid character: {c!r}")

    pos = 0
    ntok = len(tokens)

    def parse_expr():
        nonlocal pos
        value = parse_term()
        while pos < ntok and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while pos < ntok and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            rhs = parse_factor()
            if op == '*':
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("Division by zero")
                value = value / rhs
        return value

    def parse_factor():
        nonlocal pos
        if pos < ntok and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            value = parse_factor()
            return -value if op == '-' else value
        return parse_primary()

    def parse_primary():
        nonlocal pos
        if pos >= ntok:
            raise ValueError("Unexpected end of input")
        tok = tokens[pos]
        if tok == '(':
            pos += 1
            value = parse_expr()
            if pos >= ntok or tokens[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return value
        if isinstance(tok, float):
            pos += 1
            return tok
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_expr()
    if pos != ntok:
        raise ValueError("Trailing tokens")
    return float(result)

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    n, m = len(a), len(b)
    # Build LCS length table, dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    result: list[tuple[str, str]] = []
    i = j = 0
    while i < n and j < m:
        if a[i] == b[j]:
            result.append((' ', a[i]))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            # deletion (skip a[i]) preferred over insertion when tied
            result.append(('-', a[i]))
            i += 1
        else:
            result.append(('+', b[j]))
            j += 1
    while i < n:
        result.append(('-', a[i]))
        i += 1
    while j < m:
        result.append(('+', b[j]))
        j += 1
    return result

