class SlidingWindowRateLimiter:
    def __init__(self, max_calls: int, window: float):
        self.max_calls = max_calls
        self.window = window
        self._log = defaultdict(deque)

    def allow(self, key: str, now: float) -> bool:
        cutoff = now - self.window
        log = self._log[key]
        # Drop timestamps that are exactly `window` old or older (expired).
        while log and log[0] <= cutoff:
            log.popleft()
        if len(log) < self.max_calls:
            log.append(now)
            return True
        return False

def is_match(s: str, p: str) -> bool:
    memo = {}

    def dp(i: int, j: int) -> bool:
        if (i, j) in memo:
            return memo[(i, j)]
        # True if s[i:] matches p[j:]
        if j == len(p):
            result = (i == len(s))
        else:
            first_match = bool(i < len(s)) and p[j] in ('.', s[i])
            if j + 1 < len(p) and p[j + 1] == '*':
                result = dp(i, j + 2) or (first_match and dp(i + 1, j))
            else:
                result = first_match and dp(i + 1, j + 2)
        memo[(i, j)] = result
        return result

    return dp(0, 0)

def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    # dp[i][j] = True if s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Handle patterns like a*, a*b*, etc. matching empty string
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # match zero of preceding element, or one/more
                dp[i][j] = dp[i][j - 2] or (
                    dp[i - 1][j] and (s[i - 1] == p[j - 2] or p[j - 2] == '.')
                )
            else:
                if s[i - 1] == p[j - 1] or p[j - 1] == '.':
                    dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]

import string


class _Parser:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.n = len(text)

    def error(self, msg="Malformed input"):
        raise ValueError(msg)

    @staticmethod
    def _is_digit(c) -> bool:
        return c is not None and '0' <= c <= '9'

    def _is_alpha(self, c) -> bool:
        return c is not None and (c in string.ascii_letters or c == '_')

    def _is_alnum(self, c) -> bool:
        return c is not None and (c in string.ascii_letters or self._is_digit(c) or c == '_')

    def peek(self):
        if self.pos < self.n:
            return self.text[self.pos]
        return None

    def skip_ws(self):
        while self.pos < self.n:
            c = self.text[self.pos]
            if c in ' \t\n\r':
                self.pos += 1
            elif c == '/' and self.pos + 1 < self.n and self.text[self.pos + 1] == '/':
                self.pos += 2
                while self.pos < self.n and self.text[self.pos] != '\n':
                    self.pos += 1
            elif c == '/' and self.pos + 1 < self.n and self.text[self.pos + 1] == '*':
                self.pos += 2
                while self.pos + 1 < self.n and not (self.text[self.pos] == '*' and self.text[self.pos + 1] == '/'):
                    self.pos += 1
                if self.pos + 1 >= self.n:
                    self.error("Unterminated block comment")
                self.pos += 2
            else:
                break

    def parse_value(self):
        self.skip_ws()
        c = self.peek()
        if c is None:
            self.error("Unexpected end of input")
        if c == '{':
            return self.parse_object()
        if c == '[':
            return self.parse_array()
        if c == '"' or c == "'":
            return self.parse_string()
        if c == 't' or c == 'f':
            return self.parse_bool()
        if c == 'n':
            return self.parse_null()
        if c == '-' or self._is_digit(c):
            return self.parse_number()
        self.error(f"Unexpected character: {c!r}")

    def parse_object(self):
        self.pos += 1  # consume '{'
        obj = {}
        self.skip_ws()
        if self.peek() == '}':
            self.pos += 1
            return obj
        while True:
            self.skip_ws()
            key = self.parse_key()
            self.skip_ws()
            if self.peek() != ':':
                self.error("Expected ':' in object")
            self.pos += 1  # consume ':'
            obj[key] = self.parse_value()
            self.skip_ws()
            c = self.peek()
            if c == ',':
                self.pos += 1
                self.skip_ws()
                if self.peek() == '}':
                    self.pos += 1
                    return obj
            elif c == '}':
                self.pos += 1
                return obj
            else:
                self.error("Expected ',' or '}' in object")

    def parse_key(self):
        c = self.peek()
        if c == '"':
            return self.parse_string()
        if self._is_alpha(c):
            start = self.pos
            self.pos += 1
            while self.pos < self.n and self._is_alnum(self.text[self.pos]):
                self.pos += 1
            return self.text[start:self.pos]
        self.error("Expected object key")

    def parse_array(self):
        self.pos += 1  # consume '['
        arr = []
        while True:
            arr.append(self.parse_value())
            self.skip_ws()
            c = self.peek()
            if c == ',':
                self.pos += 1
                self.skip_ws()
                if self.peek() == ']':
                    self.pos += 1
                    return arr
            elif c == ']':
                self.pos += 1
                return arr
            else:
                self.error("Expected ',' or ']' in array")

    def parse_string(self):
        quote = self.text[self.pos]
        self.pos += 1
        result = []
        while True:
            if self.pos >= self.n:
                self.error("Unterminated string")
            c = self.text[self.pos]
            if c == '\\':
                self.pos += 1
                if self.pos >= self.n:
                    self.error("Unterminated escape sequence")
                esc = self.text[self.pos]
                simple = {'n': '\n', 't': '\t', 'r': '\r', '\\': '\\',
                          '"': '"', "'": "'", '/': '/', 'b': '\b', 'f': '\f'}
                if esc in simple:
                    result.append(simple[esc])
                    self.pos += 1
                elif esc == 'u':
                    if self.pos + 4 >= self.n:
                        self.error("Invalid \\u escape")
                    hexstr = self.text[self.pos + 1:self.pos + 5]
                    for h in hexstr:
                        if h not in '0123456789abcdefABCDEF':
                            self.error("Invalid \\u escape")
                    result.append(chr(int(hexstr, 16)))
                    self.pos += 5
                else:
                    self.error(f"Invalid escape sequence: \\{esc}")
            elif c == quote:
                self.pos += 1
                return ''.join(result)
            else:
                result.append(c)
                self.pos += 1

    def parse_number(self):
        start = self.pos
        if self.peek() == '-':
            self.pos += 1
        if self.peek() == '0':
            self.pos += 1
        elif self._is_digit(self.peek()):
            while self._is_digit(self.peek()):
                self.pos += 1
        else:
            self.error("Invalid number")
        if self.peek() == '.':
            self.pos += 1
            if not self._is_digit(self.peek()):
                self.error("Invalid number fraction")
            while self._is_digit(self.peek()):
                self.pos += 1
        if self.peek() in ('e', 'E'):
            self.pos += 1
            if self.peek() in ('+', '-'):
                self.pos += 1
            if not self._is_digit(self.peek()):
                self.error("Invalid number exponent")
            while self._is_digit(self.peek()):
                self.pos += 1
        numstr = self.text[start:self.pos]
        if '.' in numstr or 'e' in numstr or 'E' in numstr:
            return float(numstr)
        return int(numstr)

    def parse_bool(self):
        if self.text[self.pos:self.pos + 4] == 'true':
            self.pos += 4
            return True
        if self.text[self.pos:self.pos + 5] == 'false':
            self.pos += 5
            return False
        self.error("Invalid literal")

    def parse_null(self):
        if self.text[self.pos:self.pos + 4] == 'null':
            self.pos += 4
            return None
        self.error("Invalid literal")


def parse_relaxed(text: str):
    parser = _Parser(text)
    value = parser.parse_value()
    parser.skip_ws()
    if parser.pos != len(parser.text):
        raise ValueError("Trailing non-whitespace after top-level value")
    return value

def parse_relaxed(text: str):
    class _Parser:
        def __init__(self, text):
            self.text = text
            self.pos = 0

        def error(self, msg="Malformed input"):
            raise ValueError(msg)

        def skip_ws(self):
            n = len(self.text)
            while self.pos < n:
                c = self.text[self.pos]
                if c in ' \t\r\n':
                    self.pos += 1
                elif c == '/' and self.pos + 1 < n and self.text[self.pos + 1] == '/':
                    self.pos += 2
                    while self.pos < n and self.text[self.pos] != '\n':
                        self.pos += 1
                elif c == '/' and self.pos + 1 < n and self.text[self.pos + 1] == '*':
                    self.pos += 2
                    while self.pos + 1 < n and not (self.text[self.pos] == '*' and self.text[self.pos + 1] == '/'):
                        self.pos += 1
                    if self.pos + 1 >= n:
                        self.error("Unterminated block comment")
                    self.pos += 2
                else:
                    break

        def parse_value(self):
            self.skip_ws()
            if self.pos >= len(self.text):
                self.error("Unexpected end of input")
            c = self.text[self.pos]
            if c == '{':
                return self.parse_object()
            if c == '[':
                return self.parse_array()
            if c == '"' or c == "'":
                return self.parse_string()
            if c == 't' or c == 'f':
                return self.parse_bool()
            if c == 'n':
                return self.parse_null()
            if c == '-' or c.isdigit():
                return self.parse_number()
            self.error(f"Unexpected character: {c!r}")

        def parse_object(self):
            self.pos += 1  # consume '{'
            result = {}
            self.skip_ws()
            if self.pos < len(self.text) and self.text[self.pos] == '}':
                self.pos += 1
                return result
            while True:
                self.skip_ws()
                if self.pos >= len(self.text):
                    self.error("Unterminated object")
                c = self.text[self.pos]
                if c == '"' or c == "'":
                    key = self.parse_string()
                elif c.isalpha() or c == '_':
                    key = self.parse_key()
                else:
                    self.error(f"Expected key, got {c!r}")
                self.skip_ws()
                if self.pos >= len(self.text) or self.text[self.pos] != ':':
                    self.error("Expected ':' in object")
                self.pos += 1
                result[key] = self.parse_value()
                self.skip_ws()
                if self.pos >= len(self.text):
                    self.error("Unterminated object")
                c = self.text[self.pos]
                if c == '}':
                    self.pos += 1
                    return result
                if c == ',':
                    self.pos += 1
                    self.skip_ws()
                    if self.pos < len(self.text) and self.text[self.pos] == '}':
                        self.pos += 1
                        return result
                    continue
                self.error(f"Expected ',' or '}}', got {c!r}")

        def parse_array(self):
            self.pos += 1  # consume '['
            result = []
            self.skip_ws()
            if self.pos < len(self.text) and self.text[self.pos] == ']':
                self.pos += 1
                return result
            while True:
                result.append(self.parse_value())
                self.skip_ws()
                if self.pos >= len(self.text):
                    self.error("Unterminated array")
                c = self.text[self.pos]
                if c == ']':
                    self.pos += 1
                    return result
                if c == ',':
                    self.pos += 1
                    self.skip_ws()
                    if self.pos < len(self.text) and self.text[self.pos] == ']':
                        self.pos += 1
                        return result
                    continue
                self.error(f"Expected ',' or ']', got {c!r}")

        def parse_string(self):
            quote = self.text[self.pos]
            self.pos += 1
            out = []
            n = len(self.text)
            while self.pos < n:
                c = self.text[self.pos]
                if c == quote:
                    self.pos += 1
                    return ''.join(out)
                if c == '\\':
                    self.pos += 1
                    if self.pos >= n:
                        self.error("Unterminated escape")
                    esc = self.text[self.pos]
                    mapping = {'n': '\n', 't': '\t', '\\': '\\', '"': '"', "'": "'", '/': '/'}
                    if esc in mapping:
                        out.append(mapping[esc])
                    else:
                        self.error(f"Invalid escape: \\{esc}")
                    self.pos += 1
                elif ord(c) < 0x20:
                    self.error("Control character in string")
                else:
                    out.append(c)
                    self.pos += 1
            self.error("Unterminated string")

        def parse_key(self):
            start = self.pos
            n = len(self.text)
            while self.pos < n and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'):
                self.pos += 1
            return self.text[start:self.pos]

        def parse_number(self):
            start = self.pos
            n = len(self.text)
            if self.pos < n and self.text[self.pos] == '-':
                self.pos += 1
            if self.pos >= n or not self.text[self.pos].isdigit():
                self.error("Invalid number")
            if self.text[self.pos] == '0':
                self.pos += 1
                if self.pos < n and self.text[self.pos].isdigit():
                    self.error("Leading zeros not allowed")
            else:
                while self.pos < n and self.text[self.pos].isdigit():
                    self.pos += 1
            is_float = False
            if self.pos < n and self.text[self.pos] == '.':
                is_float = True
                self.pos += 1
                if self.pos >= n or not self.text[self.pos].isdigit():
                    self.error("Invalid number fraction")
                while self.pos < n and self.text[self.pos].isdigit():
                    self.pos += 1
            if self.pos < n and self.text[self.pos] in 'eE':
                is_float = True
                self.pos += 1
                if self.pos < n and self.text[self.pos] in '+-':
                    self.pos += 1
                if self.pos >= n or not self.text[self.pos].isdigit():
                    self.error("Invalid number exponent")
                while self.pos < n and self.text[self.pos].isdigit():
                    self.pos += 1
            num_str = self.text[start:self.pos]
            return float(num_str) if is_float else int(num_str)

        def parse_bool(self):
            if self.text[self.pos:self.pos + 4] == 'true':
                self.pos += 4
                return True
            if self.text[self.pos:self.pos + 5] == 'false':
                self.pos += 5
                return False
            self.error("Invalid literal")

        def parse_null(self):
            if self.text[self.pos:self.pos + 4] == 'null':
                self.pos += 4
                return None
            self.error("Invalid literal")

    parser = _Parser(text)
    result = parser.parse_value()
    parser.skip_ws()
    if parser.pos != len(parser.text):
        raise ValueError("Trailing non-whitespace content after top-level value")
    return result

from collections import defaultdict


def topo_batches(deps: dict[str, list[str]]) -> list[list[str]]:
    dependents = defaultdict(list)
    indegree: dict[str, int] = {}
    all_nodes: set[str] = set()

    for node, prereqs in deps.items():
        all_nodes.add(node)
        if node not in indegree:
            indegree[node] = 0
        for p in prereqs:
            all_nodes.add(p)
            if p not in indegree:
                indegree[p] = 0
            dependents[p].append(node)
            indegree[node] += 1

    current = sorted(n for n in all_nodes if indegree[n] == 0)
    result: list[list[str]] = []
    processed = 0

    while current:
        result.append(current)
        nxt: list[str] = []
        for n in current:
            processed += 1
            for dep in dependents[n]:
                indegree[dep] -= 1
                if indegree[dep] == 0:
                    nxt.append(dep)
        current = sorted(nxt)

    if processed != len(all_nodes):
        raise ValueError("graph contains a cycle")

    return result

from collections import deque


def topo_batches(deps: dict[str, list[str]]) -> list[list[str]]:
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    dependents = {node: [] for node in all_nodes}
    indegree = {node: 0 for node in all_nodes}
    for node, prereqs in deps.items():
        for p in prereqs:
            dependents[p].append(node)
            indegree[node] += 1

    level = {node: 0 for node in all_nodes}
    queue = deque(node for node in all_nodes if indegree[node] == 0)

    processed = 0
    while queue:
        node = queue.popleft()
        processed += 1
        for dep in dependents[node]:
            if level[node] + 1 > level[dep]:
                level[dep] = level[node] + 1
            indegree[dep] -= 1
            if indegree[dep] == 0:
                queue.append(dep)

    if processed != len(all_nodes):
        raise ValueError("graph contains a cycle")

    if not all_nodes:
        return []

    max_level = max(level.values())
    return [
        sorted(node for node, lv in level.items() if lv == i)
        for i in range(max_level + 1)
    ]

def unify(t1, t2):
    subst = _unify(t1, t2, {})
    if subst is None:
        return None
    return {name: resolve(term, subst) for name, term in subst.items()}


def _unify(t1, t2, subst):
    t1 = resolve(t1, subst)
    t2 = resolve(t2, subst)

    if is_var(t1) and is_var(t2):
        if t1[1] == t2[1]:
            return subst
        new = dict(subst)
        new[t1[1]] = t2
        return new

    if is_var(t1):
        if occurs(t1[1], t2):
            return None
        new = dict(subst)
        new[t1[1]] = t2
        return new

    if is_var(t2):
        if occurs(t2[1], t1):
            return None
        new = dict(subst)
        new[t2[1]] = t1
        return new

    if t1[0] != t2[0] or len(t1) != len(t2):
        return None

    for a1, a2 in zip(t1[1:], t2[1:]):
        subst = _unify(a1, a2, subst)
        if subst is None:
            return None
    return subst


def is_var(t):
    return isinstance(t, tuple) and len(t) == 2 and t[0] == 'var'


def resolve(t, subst):
    if not is_var(t):
        return (t[0],) + tuple(resolve(a, subst) for a in t[1:])
    while is_var(t) and t[1] in subst:
        t = subst[t[1]]
    return t


def occurs(name, t):
    if is_var(t):
        return t[1] == name
    return any(occurs(name, a) for a in t[1:])

def unify(t1, t2):
    subst = {}

    def occurs(var, term):
        if term[0] == 'var':
            name = term[1]
            if name == var:
                return True
            if name in subst:
                return occurs(var, subst[name])
            return False
        return any(occurs(var, arg) for arg in term[1:])

    def walk(term):
        while term[0] == 'var' and term[1] in subst:
            term = subst[term[1]]
        return term

    def resolve(term):
        if term[0] == 'var':
            name = term[1]
            return resolve(subst[name]) if name in subst else term
        return (term[0],) + tuple(resolve(arg) for arg in term[1:])

    def ut(a, b):
        a = walk(a)
        b = walk(b)
        if a == b:
            return True
        if a[0] == 'var':
            if occurs(a[1], b):
                return False
            subst[a[1]] = b
            return True
        if b[0] == 'var':
            if occurs(b[1], a):
                return False
            subst[b[1]] = a
            return True
        if a[0] != b[0] or len(a) != len(b):
            return False
        return all(ut(a[i], b[i]) for i in range(1, len(a)))

    if not ut(t1, t2):
        return None
    return {var: resolve(term) for var, term in subst.items()}

import bisect

class RangeModule:
    def __init__(self):
        self._intervals = []  # sorted list of (left, right), non-overlapping, non-adjacent

    def add_range(self, left, right):
        intervals = self._intervals
        lo = bisect.bisect_left(intervals, (left, float('-inf')))
        while lo > 0 and intervals[lo - 1][1] >= left:
            lo -= 1
        hi = bisect.bisect_right(intervals, (right, float('inf')))
        nl, nr = left, right
        for i in range(lo, hi):
            l, r = intervals[i]
            if l < nl:
                nl = l
            if r > nr:
                nr = r
        intervals[lo:hi] = [(nl, nr)]

    def query_range(self, left, right):
        if left >= right:
            return True
        intervals = self._intervals
        idx = bisect.bisect_right(intervals, (left, float('inf'))) - 1
        return idx >= 0 and intervals[idx][0] <= left and intervals[idx][1] >= right

    def remove_range(self, left, right):
        intervals = self._intervals
        lo = bisect.bisect_left(intervals, (left, float('-inf')))
        while lo > 0 and intervals[lo - 1][1] >= left:
            lo -= 1
        hi = bisect.bisect_right(intervals, (right, float('inf')))
        to_add = []
        for i in range(lo, hi):
            l, r = intervals[i]
            if l < left:
                to_add.append((l, left))
            if r > right:
                to_add.append((right, r))
        intervals[lo:hi] = to_add

import bisect

class RangeModule:
    def __init__(self):
        self._intervals = []  # sorted, non-overlapping, non-adjacent [lo, hi) pairs

    def add_range(self, left, right):
        intervals = self._intervals
        lo = bisect.bisect_left(intervals, [left])
        if lo > 0 and intervals[lo - 1][1] >= left:
            lo -= 1
        hi = bisect.bisect_right(intervals, [right, float('inf')])
        new_lo = left
        new_hi = right
        for i in range(lo, hi):
            if intervals[i][0] < new_lo:
                new_lo = intervals[i][0]
            if intervals[i][1] > new_hi:
                new_hi = intervals[i][1]
        intervals[lo:hi] = [[new_lo, new_hi]]

    def query_range(self, left, right):
        intervals = self._intervals
        hi = bisect.bisect_right(intervals, [left, float('inf')]) - 1
        if 0 <= hi < len(intervals):
            l, r = intervals[hi]
            if l <= left and right <= r:
                return True
        return False

    def remove_range(self, left, right):
        intervals = self._intervals
        lo = bisect.bisect_left(intervals, [left])
        if lo > 0 and intervals[lo - 1][1] >= left:
            lo -= 1
        hi = bisect.bisect_right(intervals, [right, float('inf')])
        new_intervals = []
        for i in range(lo, hi):
            l, r = intervals[i]
            if l < left:
                new_intervals.append([l, left])
            if r > right:
                new_intervals.append([right, r])
        intervals[lo:hi] = new_intervals

def divmod_str(a: str, b: str) -> tuple[str, str]:
    if all(ch == '0' for ch in b):
        raise ZeroDivisionError("division by zero")
    if all(ch == '0' for ch in a):
        return ('0', '0')

    DIGIT = ord('0')

    def mul_digit(s: str, q: int) -> str:
        if q == 0:
            return '0'
        out = []
        carry = 0
        for ch in reversed(s):
            prod = (ord(ch) - DIGIT) * q + carry
            out.append(prod % 10)
            carry = prod // 10
        while carry:
            out.append(carry % 10)
            carry //= 10
        out.reverse()
        return ''.join(str(d) for d in out)

    def cmp_str(x: str, y: str) -> int:
        xi = x.lstrip('0') or '0'
        yi = y.lstrip('0') or '0'
        if len(xi) != len(yi):
            return -1 if len(xi) < len(yi) else 1
        if xi < yi:
            return -1
        if xi > yi:
            return 1
        return 0

    def sub_str(x: str, y: str) -> str:
        out = []
        borrow = 0
        Ly = len(y)
        Lx = len(x)
        for i in range(Lx):
            dx = ord(x[Lx - 1 - i]) - DIGIT
            pos = Ly - 1 - i
            dy = ord(y[pos]) - DIGIT if pos >= 0 else 0
            diff = dx - dy - borrow
            if diff < 0:
                diff += 10
                borrow = 1
            else:
                borrow = 0
            out.append(diff)
        out.reverse()
        return ''.join(str(d) for d in out).lstrip('0') or '0'

    remainder = '0'
    quotient_digits = []
    for ch in a:
        digit = ord(ch) - DIGIT
        current = remainder + str(digit)
        for q in range(9, -1, -1):
            prod = mul_digit(b, q)
            if cmp_str(prod, current) <= 0:
                quotient_digits.append(q)
                remainder = sub_str(current, prod)
                break

    quotient = ''.join(str(q) for q in quotient_digits).lstrip('0') or '0'
    return (quotient, remainder)

def divmod_str(a: str, b: str) -> tuple[str, str]:
    # All big-number arithmetic uses LSB-first digit lists.
    def to_lsb(s: str):
        return [int(ch) for ch in reversed(s)]

    bd = to_lsb(b)
    if all(d == 0 for d in bd):
        raise ZeroDivisionError("division by zero")
    bd = strip_lsb = _strip_lsb(bd)

    ad = to_lsb(a)

    def _strip_lsb(digits):
        i = len(digits) - 1
        while i >= 0 and digits[i] == 0:
            i -= 1
        return digits[:i + 1]

    def compare(x, y):
        xs = _strip_lsb(x)
        ys = _strip_lsb(y)
        if len(xs) != len(ys):
            return -1 if len(xs) < len(ys) else 1
        for xi, yi in zip(xs, ys):
            if xi != yi:
                return -1 if xi < yi else 1
        return 0

    def mul_single(digits, k):
        if k == 0:
            return []
        res = []
        carry = 0
        for d in reversed(digits):
            prod = d * k + carry
            res.append(prod % 10)
            carry = prod // 10
        while carry:
            res.append(carry % 10)
            carry //= 10
        return res

    def sub(x, y):
        res = []
        borrow = 0
        for i in range(len(x)):
            yi = y[i] if i < len(y) else 0
            diff = x[i] - yi - borrow
            if diff < 0:
                diff += 10
                borrow = 1
            else:
                borrow = 0
            res.append(diff)
        return _strip_lsb(res)

    def append_digit(digits, d):
        return _strip_lsb([d] + digits)

    remainder = []
    quotient_digits = []  # MSB-first
    for d in reversed(ad):  # process dividend MSB -> LSB
        remainder = append_digit(remainder, d)
        for q in range(9, -1, -1):
            prod = mul_single(bd, q)
            if compare(prod, remainder) <= 0:
                break
        quotient_digits.append(q)
        if q:
            remainder = sub(remainder, prod)

    i = 0
    while i < len(quotient_digits) and quotient_digits[i] == 0:
        i += 1
    q_digits = quotient_digits[i:]
    q_str = ''.join(str(d) for d in q_digits) or '0'
    r_str = ''.join(str(d) for d in reversed(remainder)) or '0'
    return q_str, r_str

import copy


class _TransactionContext:
    def __init__(self, txdict):
        self._txdict = txdict

    def __enter__(self):
        self._txdict.begin()
        return self._txdict

    def __exit__(self, exc_type, exc_val, exc_tb):
        if exc_type is None:
            self._txdict.commit()
        else:
            self._txdict.rollback()
        return False


class TxDict:
    def __init__(self, *args, **kwargs):
        self._data = dict(*args, **kwargs)
        self._stack = []

    # ---- dict-like interface ----
    def __getitem__(self, key):
        return self._data[key]

    def __setitem__(self, key, value):
        self._data[key] = value

    def __delitem__(self, key):
        del self._data[key]

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __iter__(self):
        return iter(self._data)

    def get(self, key, default=None):
        return self._data.get(key, default)

    def keys(self):
        return self._data.keys()

    def items(self):
        return self._data.items()

    def values(self):
        return self._data.values()

    def __repr__(self):
        return f"TxDict({self._data!r})"

    # ---- transaction interface ----
    def begin(self):
        self._stack.append(copy.deepcopy(self._data))

    def commit(self):
        if not self._stack:
            raise RuntimeError("no active transaction")
        self._stack.pop()

    def rollback(self):
        if not self._stack:
            raise RuntimeError("no active transaction")
        state = self._stack.pop()
        self._data.clear()
        self._data.update(state)

    def transaction(self):
        return _TransactionContext(self)

