class TxDict:
    """A dict with nestable transactions (begin/commit/rollback)."""

    def __init__(self, initial=None):
        self._data = dict(initial) if initial else {}
        self._snapshots = []

    # --- dict interface ---
    def __getitem__(self, key):
        return self._data[key]

    def __setitem__(self, key, value):
        self._data[key] = value

    def __delitem__(self, key):
        del self._data[key]

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __iter__(self):
        return iter(self._data)

    def __repr__(self):
        return f"TxDict({self._data!r})"

    def get(self, key, default=None):
        return self._data.get(key, default)

    def keys(self):
        return self._data.keys()

    def values(self):
        return self._data.values()

    def items(self):
        return self._data.items()

    def update(self, *args, **kwargs):
        self._data.update(*args, **kwargs)

    def pop(self, key, *default):
        if default:
            return self._data.pop(key, default[0])
        return self._data.pop(key)

    def clear(self):
        self._data.clear()

    # --- transaction interface ---
    def begin(self):
        self._snapshots.append(dict(self._data))

    def commit(self):
        if not self._snapshots:
            raise RuntimeError("no active transaction")
        # Discard this level's rollback point; changes stay in _data,
        # so an inner commit merges into the enclosing transaction.
        self._snapshots.pop()

    def rollback(self):
        if not self._snapshots:
            raise RuntimeError("no active transaction")
        snapshot = self._snapshots.pop()
        self._data.clear()
        self._data.update(snapshot)

    @contextmanager
    def transaction(self):
        self.begin()
        try:
            yield
        except BaseException:
            self.rollback()
            raise
        else:
            self.commit()

